val=list(csv.DictReader(open(VALUES_CSV)))
target='2018-04-23T12:00:00'
best=None
for r in val:
    if r['timeseries_id'] in zone_of and r['timestamp']==target:
        v=float(r['value']); z=zone_of[r['timeseries_id']]
        if best is None or v>best[1]:
            best=(z,v)
print(best)
